{"implementation": "def solve(case):
    min_size = case['min_cluster_size']
    clusters_in = case['clusters']
    parent = case['parent']

    stability = {}
    for c in clusters_in:
        birth = c['birth_lambda']
        exits = c['point_exit_lambdas']
        if exits:
            stab = sum(e - birth for e in exits)
        else:
            stab = 0.0
        stability[c['cluster_id']] = stab

    eligible_ids = set()
    for c in clusters_in:
        if c['size'] >= min_size:
            eligible_ids.add(c['cluster_id'])

    children = {}
    for c in clusters_in:
        if c['size'] >= min_size:
            children[c['cluster_id']] = []

    root_candidates = []
    for c in clusters_in:
        cid = c['cluster_id']
        if cid not in eligible_ids:
            continue
        p = parent.get(cid)
        if p is None or p not in eligible_ids:
            root_candidates.append(cid)
        else:
            children[p].append(cid)

    def select(node):
        child_list = children.get(node, [])
        sum_child_stab = sum(stability[ch] for ch in child_list)
        if stability[node] >= sum_child_stab:
            return [node]
        else:
            selected = []
            for ch in child_list:
                selected.extend(select(ch))
            return selected

    selected_ids = []
    for root in root_candidates:
        selected_ids.extend(select(root))

    output_clusters = []
    for c in clusters_in:
        output_clusters.append({
            'cluster_id': c['cluster_id'],
            'size': c['size'],
            'stability': stability[c['cluster_id']]
        })

    return {
        'clusters': output_clusters,
        'selected_cluster_ids': selected_ids
    }
"}
